using HRIS.Api.Data; using HRIS.Api.Models; using Microsoft.EntityFrameworkCore;
namespace HRIS.Api.Repositories;
public class LetterRepository : ILetterRepository { private readonly AppDbContext _db; public LetterRepository(AppDbContext db)=>_db=db; public Task<List<LetterType>> GetTypesAsync(bool includeInactive=false)=>_db.LetterTypes.Include(x=>x.TemplateDocument).Where(x=>includeInactive||x.IsActive).OrderBy(x=>x.Name).ToListAsync(); public Task<LetterType?> GetTypeByIdAsync(int id)=>_db.LetterTypes.Include(x=>x.TemplateDocument).FirstOrDefaultAsync(x=>x.Id==id); public Task<List<LetterRequest>> GetRequestsAsync(int? employeeId=null)=>_db.LetterRequests.Include(x=>x.Employee).Include(x=>x.LetterType).Include(x=>x.IssuedDocument).Where(x=>employeeId==null||x.EmployeeId==employeeId).OrderByDescending(x=>x.CreatedAt).ToListAsync(); public Task<LetterRequest?> GetRequestByIdAsync(int id)=>_db.LetterRequests.Include(x=>x.Employee).Include(x=>x.LetterType).Include(x=>x.IssuedDocument).FirstOrDefaultAsync(x=>x.Id==id); public async Task<LetterType> AddTypeAsync(LetterType x){_db.LetterTypes.Add(x);await _db.SaveChangesAsync();return x;} public async Task UpdateTypeAsync(LetterType x)=>await _db.SaveChangesAsync(); public async Task<LetterRequest> AddRequestAsync(LetterRequest x){_db.LetterRequests.Add(x);await _db.SaveChangesAsync();return x;} public async Task UpdateRequestAsync(LetterRequest x)=>await _db.SaveChangesAsync(); }
